        private static readonly HashSet<string> FilledPaths = new(Paths.Values, StringComparer.Ordinal);

        public static string? Geometry(string key)
        {
            return Paths.GetValueOrDefault(key);
        }

        public static bool IsFilled(string geometry)
        {
            return FilledPaths.Contains(geometry);
        }
